fn main(@builtin(local_invocation_index) lid: u32, @builtin(workgroup_id) wid: vec3<u32>, @builtin(num_workgroups) nwg: vec3<u32>) {
    let tid: i32 = i32(lid);
    let bid: i32 = i32(wid.x) + i32(wid.y) * i32(nwg.x);
    if (bid >= 1i) { return; }
    var v_acc0: f32 = 0.0;
    var v_in0: f32 = 0.0;
    var v_v0: f32 = 0.0;
    var v_v1: f32 = 0.0;
    var n_e: i32 = 0i;
    n_e = ((1024i * bid) + tid);
    if (n_e < 3i) {
        v_acc0 = 0.0;
        for (var n_r0: i32 = 0i; n_r0 < 7i; n_r0 = n_r0 + 1i) {
            v_in0 = b0[((7i * n_e) + n_r0)];
            v_v0 = v_in0;
            v_acc0 = (v_acc0 + v_v0);
        }
        v_v1 = v_acc0;
        bout[n_e] = v_v1;
    }
}

